[14273] = {id=14273,name="Shady Associates",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=4755,mapID=202,description="Most of us made it here alive... but there are worgen on this side of the city as well. We're going to continue heading south once everyone's accounted for. That reminds me, someone was asking about you. A strange fellow named Vitus... he was really giving me the creeps. He kept talking about some \"forbidden knowledge\" he'd uncovered.",starts={{npcID=35840,x=0.706,y=0.548,mapID=202}},ends={{npcID=35869,x=0.712,y=0.64,mapID=202}},coords={x=0.706,y=0.548,source="quest_giver",mapID=202},questType="standard"},
[14330] = {id=14330,name="Behind Closed Doors",level=10,requiredLevel=10,faction="both",expansion=3,zoneID=405,mapID=66,description="You've discovered the location of Khan Shodo's daughter, Kherrah . She is being held behind the doors to Maraudon! The rescue attempt is certain to be risky, but if you seek the Gelkis clan's cooperation, you must free the Khan's daughter.",questType="standard"},
[14375] = {id=14375,name="Last Chance at Humanity",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=4755,mapID=202,starts={{npcID=36332,x=0.364,y=0.612,mapID=202},{npcID=36332,x=0.364,y=0.612,mapID=202}},ends={{npcID=36332,x=0.364,y=0.612,mapID=202},{npcID=36332,x=0.364,y=0.612,mapID=202}},coords={x=0.364,y=0.612,source="quest_giver",mapID=202},questType="standard"},
[14434] = {id=14434,name="Rut'theran Village",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=4755,mapID=202,starts={{npcID=36616,x=0.424,y=0.36,mapID=202},{npcID=36616,x=0.426,y=0.36,mapID=202}},ends={{npcID=36616,x=0.424,y=0.36,mapID=202},{npcID=36616,x=0.426,y=0.36,mapID=202}},coords={x=0.424,y=0.36,source="quest_giver",mapID=202},questType="standard"},
[14446] = {id=14446,name="Cataclysm!",level=30,requiredLevel=30,faction="alliance",expansion=3,zoneID=1519,mapID=84,description="Hear my words, ! The winds of change have gathered into a violent storm that sweeps across Azeroth. Have you the courage to face the true cause of our plight? Muster your resolve, , and pray for the strength and fortune to see you through the trials that await. An unexpected ally has issued a call for all that would hear. Peer into the Waters of Farseeing and behold the fate of the world!",questType="standard"},
[14447] = {id=14447,name="Takes One to Know One",level=25,requiredLevel=25,faction="none",expansion=3,zoneID=210,mapID=118,description="While we should never miss an opportunity to strike out against the Alliance, we mustn't forget about the Scourge. We won't have the numbers here to make a proper assault in the glacier for weeks, but that won't keep us from learning all we can know about their defenses. I have asked our resident death knight to advise you in this effort. After all, who better knows this enemy than they? Allow me to introduce Koltira Deathweaver.",questType="standard"},
[14448] = {id=14448,name="Takes One to Know One",level=25,requiredLevel=25,faction="none",expansion=3,zoneID=210,mapID=118,description="While we should never miss an opportunity to strike out against the Alliance, we mustn't forget about the Scourge. We won't have the numbers here to make a proper assault in the glacier for weeks, but that won't keep us from learning all we can know about their defenses. I have asked our resident death knight to advise you in this effort. After all, who better knows this enemy than they? Allow me to introduce Koltira Deathweaver.",questType="standard"},
[14467] = {id=14467,name="Alas, Gilneas!",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=4755,mapID=202,starts={{npcID=36743,x=0.264,y=0.47,mapID=202}},ends={{npcID=36743,x=0.264,y=0.47,mapID=202}},coords={x=0.264,y=0.47,source="quest_giver",mapID=202},questType="standard"},
[14481] = {id=14481,name="Into The Abyss",level=1,requiredLevel=1,faction="alliance",expansion=3,zoneID=1519,mapID=84,description="The Horde and Alliance are locked in battle with one another in the seas to the west. Below them, a great host of enemies prepares to carry out a plan that could be the undoing of us all. I am sending you to speak with the admiral of the alliance forces. Share with him the vision you have seen. Convince him to focus his attention on the true threat below, before it grows too late... To gain audience with the admiral, you must first enlist with the recruiter at the harbor.",questType="standard"},
[24573] = {id=24573,name="Honoring the Dead",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=4709,mapID=199,description="With the immediate threat gone, can you help with some grim business? We tauren do not bury our dead, we prepare the body for its return to the elements and place it at our sacred grave sites. Those killed in the Taurajo massacre have had no funeral, and I worry misguided Alliance soldiers will burn the bodies of the dead before the proper rites have been performed. , please take this totem to Taurajo and perform services for Krulmoo, Dranh, Yonada, and Omusa. They ... didn't make it out of there.",starts={{npcID=37717,x=0.414,y=0.466,mapID=199}},ends={{npcID=37717,x=0.414,y=0.466,mapID=199}},coords={x=0.414,y=0.466,source="quest_giver",mapID=199},questType="standard"},
[25047] = {id=25047,name="Broken Panther Figurine",level=10,requiredLevel=10,faction="none",expansion=3,zoneID=5095,mapID=244,description="This badly broken figurine was discarded by its last owner. However, with the right materials and your skill in jewelcrafting, it could be completely restored.",questType="standard"},
[25208] = {id=25208,name="Tell Silvia",level=15,requiredLevel=15,faction="alliance",expansion=3,zoneID=357,mapID=69,description="It seems we've found an infestation far worse than the one we expected. Cho'gall is no doubt trying to use the Gordok to gain access to the remnants of Eldre'thalas within Dire Maul, full of the forbidden powers that brought the downfall of the Shen'dralar... I am rambling. Leave me, . Tell Silvia of what you've learned. Whatever is occuring in Dire Maul must be stopped.",starts={{npcID=40052,x=0.57,y=0.554,mapID=69}},ends={{npcID=39653,x=0.568,y=0.548,mapID=69}},coords={x=0.57,y=0.554,source="quest_giver",mapID=69},questType="standard"},
[25336] = {id=25336,name="Testing the Vessel",level=15,requiredLevel=15,faction="horde",expansion=3,zoneID=357,mapID=69,description="Master Uzer'i's taught me in the ways of making spirit weapons of great power. I'll help you set on the path to make some, and you'll give me the chance to practice my craft. This vessel can shrink and trap a defeated creature inside of it. We'll need the muisek of beasts first; ironfur bears and longtooth wolves. Kill them, and use the muisek vessel to shrink and capture them before their spirits can escape.",starts={{npcID=39894,x=0.522,y=0.48,mapID=69}},ends={{npcID=39894,x=0.522,y=0.48,mapID=69}},coords={x=0.522,y=0.48,source="quest_giver",mapID=69},questType="standard"},
[25350] = {id=25350,name="The Lost Apprentice",level=15,requiredLevel=15,faction="alliance",expansion=3,zoneID=357,mapID=69,description="If you have a moment, ... One of the students I was teaching has gone to explore the darkmist ruins to the south by himself. I warned him that it was too dangerous, but he was too excited to listen. I had spoken with him earlier about an amulet that is concealed within those ruins. Now, I fear that he may have run off in search of it, because of me... Estulan has forbidden us to pursue him. If you go there, could you please look for him?",starts={{npcID=40132,x=0.572,y=0.55,mapID=69}},ends={{npcID=40129,x=0.658,y=0.628,mapID=69}},coords={x=0.572,y=0.55,source="quest_giver",mapID=69},questType="standard"},
[25363] = {id=25363,name="War on the Woodpaw",level=15,requiredLevel=15,faction="horde",expansion=3,zoneID=357,mapID=69,description="The gnolls... they are more than a nuisance. They are a constant threat to the existence of this very camp! It is irrelevant whether they are indigenous to Feralas or not; if we do not strengthen our resolve against them, we will find ourselves driven out of the entire region. The gnoll attacks against the camp have become more fevered as of late. We need your aid in thinning their numbers; bring to me ten of their manes, and I will reward you handsomely for your effort. Go!",starts={{npcID=7875,x=0.748,y=0.424,mapID=69}},ends={{npcID=7875,x=0.748,y=0.424,mapID=69}},coords={x=0.748,y=0.424,source="quest_giver",mapID=69},questType="standard"},
[25818] = {id=25818,name="Lifting the Curse",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=11,mapID=56,description="To break the curse, there must be a reckoning. Captain Halyndor damned us all to covet a forbidden artifact; the Eye of Paleth. His spirit still covets it, standing guard over the strongbox of his old ship, the Intrepid. Vanquish the soul of the one who cursed us so, . Defeat the Captain, claim his key, and spirit the Eye of Paleth far from this place.",starts={{npcID=41307,x=0.152,y=0.294,mapID=56}},ends={{npcID=112948,x=0.144,y=0.241,mapID=56}},coords={x=0.152,y=0.294,source="quest_giver",mapID=56},questType="standard"},
[26144] = {id=26144,name="Prisoners",level=30,requiredLevel=30,faction="alliance",expansion=3,zoneID=5145,mapID=204,description="The Twilight cultist dropped this key. Use it to free the Alliance prisoners in the cages inside of L'ghorek. Hurry before the prisoners become sacrifices to whatever lurks below!",questType="standard"},
[26149] = {id=26149,name="Prisoners",level=30,requiredLevel=30,faction="horde",expansion=3,zoneID=5145,mapID=204,description="The Twilight cultist dropped this key. Use it to free the Horde prisoners in the cages inside of L'ghorek. Hurry before the prisoners become sacrifices to whatever lurks below!",questType="standard"},
[26178] = {id=26178,name="Planning for the Future",level=1,requiredLevel=1,faction="both",expansion=3,zoneID=65,mapID=115,description="We must move decisively against the wolvar if we're to have a chance of survival. However, I worry that in our zeal, too many of them will be slain. The Snowfall Glade wolvar have as much right to exist as do we. You and I will see to it that they get that chance. If Elder Ko'nani hasn't asked you already, he will ask you to deal with them. While you're upon the glade to the north, I'd like you to bag up their pups and bring them back to me.",questType="standard"},
[26191] = {id=26191,name="The Culmination of Our Efforts",level=30,requiredLevel=30,faction="both",expansion=3,zoneID=5144,mapID=205,starts={{npcID=42076,x=0.29,y=0.786,mapID=205}},ends={{npcID=42076,x=0.29,y=0.786,mapID=205}},coords={x=0.29,y=0.786,source="quest_giver",mapID=205},questType="standard"},
[26412] = {id=26412,name="The Mosh'Ogg Bounty",level=10,requiredLevel=10,faction="horde",expansion=3,zoneID=33,mapID=50,description="Say... have you heard about the ogres? I got a hot tip from some fella' named Mok'thardin that they're hiding some special, magical artifact in their cave. Skeezy knows better, though. I can smell money from a Mulgore mile away, and I'll bet that ogre doodad's worth a fortune. Here's a hint: I've seen them guarding a chest up in some ruins behind their mound. Care to fetch it for me?",questType="standard"},
[26519] = {id=26519,name="He Who Controls the Ettins",level=7,requiredLevel=7,faction="alliance",expansion=3,zoneID=44,mapID=49,description="You've stumbled upon a gnoll document. The gnoll that wrote this propaganda is semi-literate: BROTHERS OF YOWLER, HEAR DIRTPAW! DIRTPAW GIVEN ORB FROM ORCS! DIRTPAW CONTROL ETTIN THINGS! DIRTPAW CRUSH HUMIES! COME GET DIRTPAW PAW-O-GRAPH IN RETHBAN CAVE. CAVE IS WEST, HIDDEN IN CANYON! You should probably investigate.",ends={{npcID=204351,x=0.18,y=0.185,mapID=49}},questType="standard"},
[26936] = {id=26936,name="Lower the Boom",level=15,requiredLevel=15,faction="horde",expansion=3,zoneID=85,mapID=18,starts={{npcID=10837,x=0.832,y=0.69,mapID=18}},ends={{npcID=10837,x=0.832,y=0.69,mapID=18}},coords={x=0.832,y=0.69,source="quest_giver",mapID=18},questType="standard"},
[27033] = {id=27033,name="Skystrider's Heart",level=5,requiredLevel=5,faction="alliance",expansion=3,zoneID=38,mapID=48,description="Opening the hatch, you find an imposing looking mechanical device hooked to several wires, gears, and who knows what else. It's easily detached. Time to bring it back to Bingles.",starts={{npcID=44618,x=0.784,y=0.764,mapID=48}},ends={{npcID=6577,x=0.816,y=0.646,mapID=48}},coords={x=0.784,y=0.764,source="quest_giver",mapID=48},questType="standard"},
