[27574] = {id=27574,name="I Never Forget a Face",level=5,requiredLevel=5,faction="horde",expansion=3,zoneID=130,mapID=21,description="You have discovered a partially digested head . Lord Godfrey perks up when he sees it. Perhaps you should give it to him.",questType="standard"},
[27861] = {id=27861,name="The Crucible of Carnage: The Bloodeye Bruiser!",level=30,requiredLevel=30,faction="none",expansion=3,zoneID=4922,mapID=241,description="I was wondering when you'd show up, ! Having a past champion of the Ring of Blood here will be a huge draw! We're gonna be rich, buddy! RICH! Anyway, this is some old Dragonmaw fighting pit. Didn't take much modification to tune it up to our uses. I put out a few feelers, and got some heavy hitters from all around Azeroth to join in the carnage. Bout time to make some gold! You know the drill, . When you're ready, let me know and we'll get this show on the road!",questType="group"},
[27862] = {id=27862,name="The Crucible of Carnage: The Bloodeye Bruiser!",level=30,requiredLevel=30,faction="none",expansion=3,zoneID=4922,mapID=241,description="Well well, if it isn't the once champion of anguish, ! I'm seeing good money in the future now that you're here! We're gonna be rollin in the dough, buddy! Filthy RICH! Anyway, this is some old Dragonmaw fighting pit. Didn't take much modification to tune it up to our uses. I put out a few feelers, and got some heavy hitters from all around Azeroth to join in the carnage. Bout time to make some gold! You know the drill, . When you're ready, let me know and we'll get this show on the road!",questType="group"},
[27930] = {id=27930,name="Devastation",level=15,requiredLevel=15,faction="both",expansion=3,zoneID=3,mapID=15,description="The coast is clear. If Rheastrasza or the egg were able to miraculously evade Deathwing's flames, they would probably need your assistance as soon as possible.",ends={{npcID=206504,x=0.188,y=0.302,mapID=15}},questType="standard"},
[27957] = {id=27957,name="Lunk No Kill",level=15,requiredLevel=15,faction="both",expansion=3,zoneID=51,mapID=32,starts={{npcID=47269,x=0.688,y=0.534,mapID=32}},ends={{npcID=47269,x=0.688,y=0.534,mapID=32}},coords={x=0.688,y=0.534,source="quest_giver",mapID=32},questType="standard"},
[28000] = {id=28000,name="Do the Imp-Possible",level=15,requiredLevel=15,faction="both",expansion=3,zoneID=361,mapID=77,description="The satyr hide their corrupted moonwell behind an impenetrable barrier of demonic fire. Their forces must have some way of getting through it. Interrogating the satyr will be useless, but the imps they consort with will be easily swayed. I have a specific one in mind, as well... In the foothills to the east, a lone imp has been seen wandering, far from the other demons. He should prove easy pickings. Weaken him with combat, and then use this enchanted sack to capture him. Then I'll do the talking...",starts={{npcID=47341,x=0.418,y=0.72,mapID=77}},ends={{npcID=47341,x=0.418,y=0.72,mapID=77}},coords={x=0.418,y=0.72,source="quest_giver",mapID=77},questType="standard"},
[28023] = {id=28023,name="Adventurers Wanted: Scarlet Monastery",level=10,requiredLevel=10,faction="alliance",expansion=3,zoneID=6109,mapID=18,description="King Anduin Wrynn has requested able-bodied adventurers to assault the Scarlet Monastery , northeast of the Undercity, immediately! Repeated efforts to negotiate with the Scarlet Crusade have failed. Their zealotry is wreaking havoc across the reclaimed plaguelands and elsewhere. Report to the Scarlet Monastery to dish out the King's justice. Use of deadly force is encouraged!",questType="dungeon"},
[28053] = {id=28053,name="Lunk Like Your Style",level=15,requiredLevel=15,faction="both",expansion=3,zoneID=51,mapID=32,starts={{npcID=47429,x=0.396,y=0.68,mapID=32}},ends={{npcID=47429,x=0.396,y=0.68,mapID=32}},coords={x=0.396,y=0.68,source="quest_giver",mapID=32},questType="standard"},
