[28698] = {id=28698,name="Cannonball!",level=35,requiredLevel=35,faction="horde",expansion=3,zoneID=5389,mapID=245,description="Largo and his minions have been stealing our supplies ever since we setup camp here. It's frustrating to say the least. We have heard reports that he is stockpiling cannonballs in the towers overlooking the water up on his overlook. Can you head up there and try to recover some of them for us? , don't forget to keep a watch out for Alliance too.",starts={{npcID=48361,x=0.556,y=0.786,mapID=245}},ends={{npcID=48361,x=0.556,y=0.786,mapID=245}},coords={x=0.556,y=0.786,source="quest_giver",mapID=245},questType="standard"},
[28753] = {id=28753,name="Doing it the Hard Way",level=30,requiredLevel=30,faction="both",expansion=3,zoneID=4945,description="Blast it all! Someone's gone and corrupted the entire system! There be no way fer me ta access the main repository from this console. We're gunna hafta do this the hard way, . I hope you an' yer friends here are up to a fight. There be four guardians on the upper level of this place. I won't be able ta utilize these discs 'til they be... uhh, offline, shall we say.",questType="dungeon"},
[28775] = {id=28775,name="Broken Serpent Figurine",level=10,requiredLevel=10,faction="none",expansion=3,zoneID=3805,mapID=2437,description="This badly broken figurine was discarded by its last owner. However, with the right materials and your skill in jewelcrafting, it could be completely restored.",questType="standard"},
