[29180] = {id=29180,name="Promises, Promises...",level=5,requiredLevel=5,faction="both",expansion=3,zoneID=3805,mapID=2437,description="My inscrutable theories confirm rumors of vast treasure in Zul'Aman . There'll be mounts and mansions for everyone! First things first, though. You must earn your share, after all.... Our initial efforts here haven't gone as well as I hoped. In fact, my map, and the recruits I lent it to, have gone missing. They were after a troll-beast named Nalorakk. Forget the crew, I need that map! Succeed, and you'll go down in history as the one who helped Budd Nedreck unlock the secrets of Zul'Aman !",questType="dungeon"},
[29184] = {id=29184,name="X Marks... Your Doom!",level=5,requiredLevel=5,faction="none",expansion=3,zoneID=3805,mapID=2437,description="How did those fools fail? I told them to be careful - even gave them disguises to help them blend in. Ahh, well. The bright side of their failure is that this opportunity falls to you. Succeed, and you'll be well on your way to joining my crew and sharing in the immeasurable fame that will soon be mine. Not that I need any more, mind you. There are yet a few portions of my map that require further exploration before our excavation can be initiated....",questType="dungeon"},
[29185] = {id=29185,name="Daily Tier 2 Heroic (1st)",level=35,requiredLevel=35,faction="none",expansion=3,questType="standard"},
[29187] = {id=29187,name="Tuskin' Raiders",level=5,requiredLevel=5,faction="none",expansion=3,zoneID=3805,mapID=2437,description="'Ey mon! You be new around 'ere, eh? Lemme ask a favor of ya. Budd's been refinin' his forest troll disguise. Says that he be close now - just be needin' one last touch. Tusks. My skinnin' talents be wasted 'ere. Somethin' about yankin' troll tusks be makin me queasy. Bring me back 10 troll tusks, eh mon?",questType="dungeon"},
[29208] = {id=29208,name="An Old Friend",level=35,requiredLevel=35,faction="both",expansion=3,zoneID=1977,mapID=210,starts={{npcID=52877,x=0.612,y=0.814,mapID=210}},ends={{npcID=52877,x=0.612,y=0.814,mapID=210}},coords={x=0.612,y=0.814,source="quest_giver",mapID=210},questType="standard"},
