[29372] = {id=29372,name="Trouble in Podunk",level=1,requiredLevel=1,faction="both",expansion=3,zoneID=4922,mapID=241,description="Outlaws have kidnapped the sheriff!",questType="standard"},
[29373] = {id=29373,name="Trouble in Podunk",level=1,requiredLevel=1,faction="both",expansion=3,zoneID=4922,mapID=241,description="We never paid no heed to Sheriff Blundy, what with his gettin' all up-in-arms at all times 'bout his \"laws\" and his \"mis-de-meanors.\" But them dirty ol' McClintocks, and their cattle-rustlin' pappy up in Truckshaw ridge done had it up to here with the frequent incarcerations and trials and posse-gatherin' and dead-or-alive-wantin', and come this past week they done took the law into their own hands - in the most literal of senses - by haulin' up and hi-jackin' the good Sheriff. As you can see, our humble",questType="standard"},
[29382] = {id=29382,name="Thanks, But No Thanks",level=1,requiredLevel=1,faction="none",expansion=3,description="A holiday sweater may not be for everyone. The receipt says that you can exchange it for gold at any Smokywood Pastures merchant. All exchanges are final.",questType="standard"},
[29383] = {id=29383,name="Thanks, But No Thanks",level=1,requiredLevel=1,faction="none",expansion=3,description="A holiday sweater may not be for everyone. The receipt says that you can exchange it for gold at any Smokywood Pastures merchant. All exchanges are final.",questType="standard"},
